"  const handlePreOrderKOTAction = (isPrint = false) => {
    if (cart.length === 0) {
      toast.error("Cart is empty!");
      return;
    }
    if (!customerName || !customerName.trim()) {
      toast.error("Customer Name is mandatory for Pre-Order!");
      return;
    }
    if (!customerPhone || !customerPhone.trim()) {
      toast.error("Customer Phone is mandatory for Pre-Order!");
      return;
    }
    if (!preOrderScheduledDate || !preOrderScheduledTime) {
      toast.error("Scheduled Date and Time are mandatory for Pre-Order!");
      return;
    }

    const isExistingTemp = selectedTable && selectedTable.is_temporary;
    const tempId = isExistingTemp ? selectedTable.id : `temp-${Date.now()}`;
    const tableName = isExistingTemp 
      ? selectedTable.table_name 
      : `Pre-Order #${Math.floor(1000 + Math.random() * 9000)}`;

    const newTempTable = {
      id: tempId,
      table_name: tableName,
      department_name: 'Pre-Order',
      is_temporary: true,
      original_order_type: 'PRE_ORDER',
      original_sub_order_type: 'PRE_ORDER'
    };

    const bNo = tableBillNumbers[tempId] || nextBillNo;
    if (!tableBillNumbers[tempId]) {
      setNextBillNo(prev => prev + 1);
    }

    if (!isExistingTemp) {
      setTables(prev => [...prev, newTempTable]);
    } else {
      setTables(prev => prev.map(t => t.id === tempId ? newTempTable : t));
    }

    setTableBillNumbers(prev => ({ ...prev, [tempId]: bNo }));
    const cartWithKotNo = cart.map(i => ({ ...i, kotNo: bNo }));
    setTableBills(prev => ({ ...prev, [tempId]: [...cartWithKotNo] }));
    setTableActiveTimestamps(prev => ({ ...prev, [tempId]: Date.now() }));
    setTableStatuses(prev => ({ ...prev, [tempId]: isPrint ? 'PRINTED' : 'SAVED' }));

    if (isPrint) {
      handlePrintKOT(cart, tableName, bNo);
    }

    setSelectedTable(newTempTable);
    setPreOrderSubTab('PAYMENTS');
    toast.success(isPrint ? "KOT Printed & Saved!" : "KOT Saved!");
  };

